class Solution:
    def isMatch(self, s, p):
        i = j = 0
        star = -1
        match = 0
        while i < len(s):
            if j < len(p) and (p[j] == '?' or p[j] == s[i]):
                i += 1; j += 1
            elif j < len(p) and p[j] == '*':
                star = j; match = i; j += 1
            elif star != -1:
                j = star + 1; match += 1; i = match
            else:
                return False
        return all(ch == '*' for ch in p[j:])

